package attest

import (
	"context"
	"encoding/binary"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
	"time"
)

// TPM 2.0 Constants defined in TCG TPM 2.0 Part 2 (Structures).
const (
	// TPMGeneratedMagic is the 4-byte big-endian magic value (0xff544347 / "\xffTCG")
	// identifying structures generated by a TPM 2.0 chip.
	TPMGeneratedMagic uint32 = 0xff544347

	// TPMStAttestQuote is the structure tag (0x8018) for quote attestation structures (TPMS_ATTEST).
	TPMStAttestQuote uint16 = 0x8018
)

// TPMConfig specifies validation rules for TPM 2.0 quotes and PCR measurements.
type TPMConfig struct {
	// ExpectedPCRDigest optionally enforces that the composite PCR digest matches this value (hex or raw).
	ExpectedPCRDigest string

	// ExpectedPCRs optionally enforces specific individual PCR measurement registers by index.
	ExpectedPCRs map[int]string

	// ExpectedNonce optionally enforces that the quote extraData matches the issued challenge nonce.
	ExpectedNonce string

	// MaxAge specifies the maximum allowed age of the attestation quote. A zero value skips freshness validation.
	MaxAge time.Duration

	// Platform overrides the default platform identifier (e.g. "windows-desktop" or "linux-desktop").
	Platform string

	// Clock provides the time reference for freshness checks. Defaults to time.Now.
	Clock func() time.Time
}

// TPMVerifier validates TPM 2.0 quote structures and PCR register measurements.
type TPMVerifier struct {
	platform          string
	expectedPCRDigest string
	expectedPCRs      map[int]string
	expectedNonce     string
	maxAge            time.Duration
	clock             func() time.Time
}

// NewTPMVerifier creates a TPMVerifier for the "tpm" platform with default settings.
func NewTPMVerifier() *TPMVerifier {
	return NewTPMVerifierWithConfig(TPMConfig{
		Platform: PlatformTPM,
	})
}

// NewTPMVerifierWithPlatform creates a TPMVerifier configured for a specific platform name
// (e.g., "windows-desktop" or "linux-desktop").
func NewTPMVerifierWithPlatform(platform string) *TPMVerifier {
	if platform == "" {
		platform = PlatformTPM
	}
	return NewTPMVerifierWithConfig(TPMConfig{
		Platform: platform,
	})
}

// NewTPMVerifierWithConfig creates a TPMVerifier with customized PCR and nonce expectations.
func NewTPMVerifierWithConfig(config TPMConfig) *TPMVerifier {
	clock := config.Clock
	if clock == nil {
		clock = time.Now
	}
	platform := config.Platform
	if platform == "" {
		platform = PlatformTPM
	}

	return &TPMVerifier{
		platform:          platform,
		expectedPCRDigest: normalizeHex(config.ExpectedPCRDigest),
		expectedPCRs:      config.ExpectedPCRs,
		expectedNonce:     strings.TrimSpace(config.ExpectedNonce),
		maxAge:            config.MaxAge,
		clock:             clock,
	}
}

// Platform returns the platform identifier handled by this verifier.
func (verifier *TPMVerifier) Platform() string {
	return verifier.platform
}

// Verify evaluates TPM 2.0 quote binary structures or structured JSON representations.
func (verifier *TPMVerifier) Verify(ctx context.Context, evidence []byte) (*Result, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}

	payload, err := decodeEvidencePayload(evidence)
	if err != nil {
		return nil, err
	}

	// 1. Try parsing as binary TPM 2.0 TPMS_ATTEST structure
	if quoteResult, ok, parseErr := verifier.tryParseBinaryQuote(payload); ok {
		if parseErr != nil {
			return nil, parseErr
		}
		return quoteResult, nil
	}

	// 2. Parse as structured JSON quote
	return verifier.parseJSONQuote(payload)
}

func (verifier *TPMVerifier) tryParseBinaryQuote(data []byte) (*Result, bool, error) {
	// Minimum length check: magic(4) + type(2) + signerSize(2) + extraDataSize(2) + clock(8) + reset(4) + restart(4) + safe(1) + fw(8) + pcrSelect(4) + pcrDigestSize(2) = 41 bytes
	if len(data) < 41 {
		return nil, false, nil
	}

	magic := binary.BigEndian.Uint32(data[0:4])
	if magic != TPMGeneratedMagic {
		return nil, false, nil
	}

	quoteType := binary.BigEndian.Uint16(data[4:6])
	if quoteType != TPMStAttestQuote {
		return nil, true, fmt.Errorf("%w: unexpected TPM structure tag 0x%04x (expected quote 0x%04x)", ErrInvalidEvidence, quoteType, TPMStAttestQuote)
	}

	offset := 6

	// qualifiedSigner (TPM2B_NAME)
	if offset+2 > len(data) {
		return nil, true, fmt.Errorf("%w: truncated qualifiedSigner header", ErrInvalidEvidence)
	}
	signerLen := int(binary.BigEndian.Uint16(data[offset : offset+2]))
	offset += 2
	if offset+signerLen > len(data) {
		return nil, true, fmt.Errorf("%w: truncated qualifiedSigner payload", ErrInvalidEvidence)
	}
	signerBytes := data[offset : offset+signerLen]
	offset += signerLen

	// extraData (TPM2B_DATA) - nonce
	if offset+2 > len(data) {
		return nil, true, fmt.Errorf("%w: truncated extraData header", ErrInvalidEvidence)
	}
	extraDataLen := int(binary.BigEndian.Uint16(data[offset : offset+2]))
	offset += 2
	if offset+extraDataLen > len(data) {
		return nil, true, fmt.Errorf("%w: truncated extraData payload", ErrInvalidEvidence)
	}
	nonceBytes := data[offset : offset+extraDataLen]
	nonceStr := string(nonceBytes)
	offset += extraDataLen

	// clockInfo: clock(8), resetCount(4), restartCount(4), safe(1)
	if offset+17 > len(data) {
		return nil, true, fmt.Errorf("%w: truncated clockInfo", ErrInvalidEvidence)
	}
	clock := binary.BigEndian.Uint64(data[offset : offset+8])
	resetCount := binary.BigEndian.Uint32(data[offset+8 : offset+12])
	restartCount := binary.BigEndian.Uint32(data[offset+12 : offset+16])
	safeByte := data[offset+16]
	isSafe := safeByte == 1
	offset += 17

	// firmwareVersion (8 bytes)
	if offset+8 > len(data) {
		return nil, true, fmt.Errorf("%w: truncated firmwareVersion", ErrInvalidEvidence)
	}
	firmwareVersion := binary.BigEndian.Uint64(data[offset : offset+8])
	offset += 8

	// TPMS_QUOTE_INFO:
	// pcrSelect (TPML_PCR_SELECTION): count (4 bytes) + array of selections
	if offset+4 > len(data) {
		return nil, true, fmt.Errorf("%w: truncated pcrSelect count", ErrInvalidEvidence)
	}
	pcrSelectCount := int(binary.BigEndian.Uint32(data[offset : offset+4]))
	offset += 4

	for selectionIdx := 0; selectionIdx < pcrSelectCount; selectionIdx++ {
		if offset+3 > len(data) {
			return nil, true, fmt.Errorf("%w: truncated pcrSelect entry", ErrInvalidEvidence)
		}
		// hashAlg uint16(2), size uint8(1)
		selSize := int(data[offset+2])
		offset += 3 + selSize
		if offset > len(data) {
			return nil, true, fmt.Errorf("%w: pcrSelect entry overflow", ErrInvalidEvidence)
		}
	}

	// pcrDigest (TPM2B_DIGEST): size (uint16) + digest
	if offset+2 > len(data) {
		return nil, true, fmt.Errorf("%w: truncated pcrDigest size", ErrInvalidEvidence)
	}
	pcrDigestLen := int(binary.BigEndian.Uint16(data[offset : offset+2]))
	offset += 2
	if offset+pcrDigestLen > len(data) {
		return nil, true, fmt.Errorf("%w: truncated pcrDigest bytes", ErrInvalidEvidence)
	}
	pcrDigestBytes := data[offset : offset+pcrDigestLen]
	pcrDigestHex := hex.EncodeToString(pcrDigestBytes)

	// Validate against expectations
	if verifier.expectedNonce != "" && nonceStr != verifier.expectedNonce && hex.EncodeToString(nonceBytes) != verifier.expectedNonce {
		return nil, true, fmt.Errorf("%w: nonce mismatch (got %q, expected %q)", ErrIntegrityCheckFailed, nonceStr, verifier.expectedNonce)
	}

	if verifier.expectedPCRDigest != "" && !strings.EqualFold(pcrDigestHex, verifier.expectedPCRDigest) {
		return nil, true, fmt.Errorf("%w: PCR digest mismatch (got %s, expected %s)", ErrIntegrityCheckFailed, pcrDigestHex, verifier.expectedPCRDigest)
	}

	now := verifier.clock()
	var warnings []string
	if !isSafe {
		warnings = append(warnings, "TPM clock is marked unsafe (possible reset, sleep, or power loss)")
	}
	if resetCount > 0 {
		warnings = append(warnings, fmt.Sprintf("TPM reset count is %d", resetCount))
	}

	details := map[string]string{
		"attestation_type":  "tpm2.0_binary_quote",
		"pcr_digest":        pcrDigestHex,
		"nonce":             nonceStr,
		"clock":             strconv.FormatUint(clock, 10),
		"reset_count":       strconv.FormatUint(uint64(resetCount), 10),
		"restart_count":     strconv.FormatUint(uint64(restartCount), 10),
		"firmware_version":  strconv.FormatUint(firmwareVersion, 10),
		"safe":              strconv.FormatBool(isSafe),
		"qualified_signer":  hex.EncodeToString(signerBytes),
	}

	appIdentity := fmt.Sprintf("tpm-fw-%d", firmwareVersion)

	return &Result{
		Platform:        verifier.platform,
		Verified:        true,
		AppIdentity:     appIdentity,
		DeviceIntegrity: IntegrityStrong,
		Timestamp:       now.Unix(),
		Details:         details,
		Warnings:        warnings,
	}, true, nil
}

type tpmJSONQuote struct {
	Magic           any               `json:"magic"`
	Type            any               `json:"type"`
	PCRDigest       string            `json:"pcr_digest"`
	PCRs            map[string]string `json:"pcrs"`
	Nonce           string            `json:"nonce"`
	Clock           any               `json:"clock"`
	ResetCount      any               `json:"reset_count"`
	RestartCount    any               `json:"restart_count"`
	Safe            *bool             `json:"safe"`
	FirmwareVersion any               `json:"firmware_version"`
	AppIdentity     string            `json:"app_identity"`
	DeviceIntegrity string            `json:"device_integrity"`
	Timestamp       int64             `json:"timestamp"`
	ExpiresAt       int64             `json:"expires_at"`
}

func (verifier *TPMVerifier) parseJSONQuote(data []byte) (*Result, error) {
	var payload tpmJSONQuote
	if err := json.Unmarshal(data, &payload); err != nil {
		return nil, fmt.Errorf("%w: %w", ErrInvalidEvidence, err)
	}

	// 1. Validate magic or type indicator if present
	if payload.Magic != nil {
		switch m := payload.Magic.(type) {
		case string:
			if !strings.EqualFold(m, "TPM_GENERATED") && !strings.EqualFold(m, "0xff544347") {
				return nil, fmt.Errorf("%w: invalid TPM magic string %q", ErrInvalidEvidence, m)
			}
		case float64:
			if uint32(m) != TPMGeneratedMagic {
				return nil, fmt.Errorf("%w: invalid TPM magic number 0x%08x", ErrInvalidEvidence, uint32(m))
			}
		}
	}

	// 2. Freshness and Timestamp
	now := verifier.clock()
	tokenTimeSec := parseTimestampSeconds(payload.Timestamp)
	if payload.ExpiresAt > 0 && now.Unix() > payload.ExpiresAt {
		return nil, ErrEvidenceExpired
	}
	if verifier.maxAge > 0 && tokenTimeSec > 0 {
		tokenTime := time.Unix(tokenTimeSec, 0)
		if now.Sub(tokenTime) > verifier.maxAge {
			return nil, ErrEvidenceExpired
		}
	}
	if tokenTimeSec == 0 {
		tokenTimeSec = now.Unix()
	}

	// 3. Validate PCR Digest
	pcrDigest := normalizeHex(payload.PCRDigest)
	if verifier.expectedPCRDigest != "" && !strings.EqualFold(pcrDigest, verifier.expectedPCRDigest) {
		return nil, fmt.Errorf("%w: PCR digest mismatch (got %s, expected %s)", ErrIntegrityCheckFailed, pcrDigest, verifier.expectedPCRDigest)
	}

	// 4. Validate individual PCR registers if required
	if len(verifier.expectedPCRs) > 0 {
		for idx, expectedVal := range verifier.expectedPCRs {
			expectedNormalized := normalizeHex(expectedVal)
			keyStr := strconv.Itoa(idx)
			actualVal, exists := payload.PCRs[keyStr]
			if !exists {
				return nil, fmt.Errorf("%w: missing required PCR %d measurement", ErrIntegrityCheckFailed, idx)
			}
			if !strings.EqualFold(normalizeHex(actualVal), expectedNormalized) {
				return nil, fmt.Errorf("%w: PCR %d measurement mismatch (got %s, expected %s)", ErrIntegrityCheckFailed, idx, actualVal, expectedVal)
			}
		}
	}

	// 5. Validate Nonce
	if verifier.expectedNonce != "" && payload.Nonce != verifier.expectedNonce {
		return nil, fmt.Errorf("%w: nonce mismatch (got %q, expected %q)", ErrIntegrityCheckFailed, payload.Nonce, verifier.expectedNonce)
	}

	// 6. Device Integrity and Warnings
	deviceIntegrity := IntegrityStrong
	if payload.DeviceIntegrity != "" {
		switch strings.ToLower(payload.DeviceIntegrity) {
		case IntegrityStrong:
			deviceIntegrity = IntegrityStrong
		case IntegrityBasic:
			deviceIntegrity = IntegrityBasic
		case IntegrityNone:
			deviceIntegrity = IntegrityNone
		}
	}

	var warnings []string
	if payload.Safe != nil && !*payload.Safe {
		warnings = append(warnings, "TPM clock is marked unsafe (possible reset or unverified power state)")
	}

	appIdentity := payload.AppIdentity
	if appIdentity == "" {
		if payload.FirmwareVersion != nil {
			appIdentity = fmt.Sprintf("tpm-fw-%v", payload.FirmwareVersion)
		} else {
			appIdentity = "tpm2.0-host"
		}
	}

	details := make(map[string]string)
	if pcrDigest != "" {
		details["pcr_digest"] = pcrDigest
	}
	if payload.Nonce != "" {
		details["nonce"] = payload.Nonce
	}
	if payload.Clock != nil {
		details["clock"] = fmt.Sprintf("%v", payload.Clock)
	}
	if payload.ResetCount != nil {
		details["reset_count"] = fmt.Sprintf("%v", payload.ResetCount)
	}
	if payload.FirmwareVersion != nil {
		details["firmware_version"] = fmt.Sprintf("%v", payload.FirmwareVersion)
	}

	return &Result{
		Platform:        verifier.platform,
		Verified:        deviceIntegrity != IntegrityNone,
		AppIdentity:     appIdentity,
		DeviceIntegrity: deviceIntegrity,
		Timestamp:       tokenTimeSec,
		Details:         details,
		Warnings:        warnings,
	}, nil
}

func normalizeHex(val string) string {
	val = strings.TrimSpace(val)
	val = strings.TrimPrefix(val, "0x")
	val = strings.TrimPrefix(val, "0X")
	return strings.ToLower(val)
}
